def choose_move(observation):
    # Defensive defaults
    x = observation.get("self_x", 0)
    y = observation.get("self_y", 0)
    width = observation.get("width", 0)
    height = observation.get("height", 0)

    # Helper to clamp to grid
    def clamp(v, lo, hi):
        if v < lo:
            return lo
        if v > hi:
            return hi
        return v

    # Initialize candidate moves (dx, dy) within {-1,0,1}
    moves = [(-1,-1), (-1,0), (-1,1),
             (0,-1),  (0,0),  (0,1),
             (1,-1),  (1,0),  (1,1)]

    # Observe environment defensively
    # Try to detect simple signals for each of the three modes
    # Resource collection: look for closest resource
    resources = observation.get("resources", [])
    enemies = observation.get("enemies", [])
    territories = observation.get("territories", [])

    # Helper: compute Manhattan distance
    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    best_move = (0, 0)
    best_score = -10**9

    # Use a simple heuristic scoring per candidate move
    for dx, dy in moves:
        nx = clamp(x + dx, 0, width - 1) if width > 0 else x + dx
        ny = clamp(y + dy, 0, height - 1) if height > 0 else y + dy

        score = 0

        # Resource collection: approach closest resource
        if resources:
            # find nearest resource
            try:
                nearest = min(resources, key=lambda r: dist((nx, ny), (r.get("x", nx), r.get("y", ny))))
                d = dist((nx, ny), (nearest.get("x", nx), nearest.get("y", ny)))
                # reward closer to resource
                score += max(0, 10 - d)
            except Exception:
                pass

        # Pursuit-evasion: tend to pursue or evade based on evaders
        if enemies:
            # If evader close, prefer moving towards or away depending on simple rule
            try:
                nearest_e = min(enemies, key=lambda e: dist((nx, ny), (e.get("x", nx), e.get("y", ny))))
                d_e = dist((nx, ny), (nearest_e.get("x", nx), nearest_e.get("y", ny)))
                # If evader is close, prefer moving away; otherwise small incentive to approach
                if d_e <= 2:
                    score += 5 * (1 if (dx == -1 or dy == -1) else -1)
                    score += -d_e
                else:
                    score += max(0, 3 - d_e)
            except Exception:
                pass

        # Territory control: prefer moving towards most-protected/owned area
        if territories:
            try:
                # heuristic: move toward closest owned territory cell
                owned = [t for t in territories if t.get("owner") == "self"]
                if owned:
                    nearest_t = min(owned, key=lambda c: dist((nx, ny), (c.get("x", nx), c.get("y", ny))))
                    d_t = dist((nx, ny), (nearest_t.get("x", nx), nearest_t.get("y", ny)))
                    score += max(0, 4 - d_t)
            except Exception:
                pass

        # Boundary avoidance: discourage leaving bounds when grid is defined
        if width > 0 and height > 0:
            if nx == 0 or ny == 0 or nx == width - 1 or ny == height - 1:
                score -= 1  # discourage edge hugging

        if score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

